import re, subprocess, collections, os
files = subprocess.check_output(['bash','-c','find . -name "*.go" -not -path "./web/*" -not -path "./node_modules/*"']).decode().split()
decls = {}  # name -> list of (file,line)
funcre = re.compile(r'^func\s+(?:\([^)]*\)\s*)?([A-Za-z_][A-Za-z0-9_]*)\s*[\(\[]')
contents = {}
for f in files:
    txt = open(f, encoding='utf-8', errors='replace').read()
    contents[f]=txt
    if not f.startswith('./internal/'): continue
    for i,l in enumerate(txt.split('\n'),1):
        m = funcre.match(l)
        if m:
            decls.setdefault(m.group(1), []).append((f,i,l.strip()))

counts = collections.Counter()
for name in decls:
    if name in ('init','main','String','Error'): continue
    pat = re.compile(r'\b'+re.escape(name)+r'\s*\(')
    c = 0
    for f,txt in contents.items():
        for i,l in enumerate(txt.split('\n'),1):
            if funcre.match(l): 
                m=funcre.match(l)
                if m.group(1)==name: continue
            c += len(pat.findall(l))
    counts[name]=c
for name,c in counts.most_common(25):
    print(c, name, decls[name][:2])
EOF

