import re, subprocess, collections
files = subprocess.check_output(['bash','-c','find . -name "*.go" -not -path "./web/*"']).decode().split()
contents = {f: open(f,encoding='utf-8',errors='replace').read() for f in files}
funcre = re.compile(r'^func\s+(?:\(\s*\w+\s+\*?(\w+)\s*\)\s*)?([A-Za-z_]\w*)\s*[\(\[]')
decls=[]
for f in files:
    if not f.startswith('./internal/'): continue
    pkg = f.split('/')[2] if len(f.split('/'))>3 else f.split('/')[2]
    # package name = last dir
    import os
    pkgdir = os.path.dirname(f)
    pkgname = os.path.basename(pkgdir)
    for i,l in enumerate(contents[f].split('\n'),1):
        m=funcre.match(l)
        if m:
            decls.append((m.group(1), m.group(2), f, i, pkgname))

res=[]
for recv,name,f,i,pkgname in decls:
    if recv: pat = re.compile(r'\.'+re.escape(name)+r'\s*\(')
    else:
        if not name[0].isupper():
            pat = re.compile(r'(?<![\w.])'+re.escape(name)+r'\s*\(')
        else:
            pat = re.compile(re.escape(pkgname)+r'\.'+re.escape(name)+r'\s*\(')
    tot=0; test=0
    for ff,txt in contents.items():
        if recv is None and not name[0].isupper() and not ff.startswith(os.path.dirname(f)): continue
        n=len(pat.findall(txt))
        tot+=n
        if ff.endswith('_test.go'): test+=n
    res.append((tot, tot-test, f'{recv+"." if recv else pkgname+"."}{name}', f, i))
res.sort(reverse=True)
for r in res[:25]: print(r)
EOF

