    for l in contents[f].split('\n'):
        m=funcre.match(l)
        if m: allmethods.setdefault(m.group(2),set()).add((m.group(1),f))
decls=[]
for f in files:
    if not f.startswith('./internal/') or f.endswith('_test.go'): continue
    pkgname=os.path.basename(os.path.dirname(f))
    for i,l in enumerate(contents[f].split('\n'),1):
        m=funcre.match(l)
        if m: decls.append((m.group(1),m.group(2),f,i,pkgname))
res=[]
for recv,name,f,i,pkgname in decls:
    ambiguous = len(allmethods[name])>1
    if recv: pat=re.compile(r'\.'+re.escape(name)+r'\s*\(')
    elif name[0].isupper(): pat=re.compile(re.escape(pkgname)+r'\.'+re.escape(name)+r'\s*\(')
    else: pat=re.compile(r'(?<![\w.])'+re.escape(name)+r'\s*\(')
    tot=0;nontest=0
    for ff,txt in contents.items():
        if not recv and not name[0].isupper() and os.path.dirname(ff)!=os.path.dirname(f): continue
        for line in txt.split('\n'):
            mm=funcre.match(line)
            if mm and mm.group(2)==name: continue
            n=len(pat.findall(line))
            tot+=n
            if not ff.endswith('_test.go'): nontest+=n
    res.append((tot,nontest,('AMBIG ' if ambiguous else '')+f'{recv+"." if recv else pkgname+"."}{name}',f,i))
res.sort(reverse=True)
for r in res[:30]: print(r)
EOF

